// Tiny dependency-free ZIP writer/reader for *stored* entries; avoids third-party CDN.
// Import only supports uncompressed ZIPs generated by this app.
const enc=new TextEncoder(),dec=new TextDecoder();
const table=Array.from({length:256},(_,n)=>{let c=n;for(let k=0;k<8;k++)c=(c&1)?0xedb88320^(c>>>1):c>>>1;return c>>>0});
function crc32(a){let c=0xffffffff;for(const b of a)c=table[(c^b)&255]^(c>>>8);return(c^0xffffffff)>>>0}
function u16(v,n,x){v.setUint16(n,x,true)}function u32(v,n,x){v.setUint32(n,x,true)}
function bytes(x){return typeof x==='string'?enc.encode(x):x instanceof Uint8Array?x:new Uint8Array(x)}
export function makeZip(entries){let parts=[],central=[],offset=0;for(const [name,body] of entries){const nb=enc.encode(name),data=bytes(body),crc=crc32(data),local=new Uint8Array(30+nb.length),view=new DataView(local.buffer);u32(view,0,0x04034b50);u16(view,4,20);u16(view,6,0x800);u32(view,14,crc);u32(view,18,data.length);u32(view,22,data.length);u16(view,26,nb.length);local.set(nb,30);parts.push(local,data);const item=new Uint8Array(46+nb.length),cv=new DataView(item.buffer);u32(cv,0,0x02014b50);u16(cv,4,20);u16(cv,6,20);u16(cv,8,0x800);u32(cv,16,crc);u32(cv,20,data.length);u32(cv,24,data.length);u16(cv,28,nb.length);u32(cv,42,offset);item.set(nb,46);central.push(item);offset+=local.length+data.length;}const csize=central.reduce((n,a)=>n+a.length,0),end=new Uint8Array(22),e=new DataView(end.buffer);u32(e,0,0x06054b50);u16(e,8,central.length);u16(e,10,central.length);u32(e,12,csize);u32(e,16,offset);return new Blob([...parts,...central,end],{type:'application/zip'})}
export async function readZip(file){const b=new Uint8Array(await file.arrayBuffer()),v=new DataView(b.buffer),out=new Map();let i=0;while(i+4<=b.length){const sig=v.getUint32(i,true);if(sig!==0x04034b50)break;const flags=v.getUint16(i+6,true),method=v.getUint16(i+8,true),size=v.getUint32(i+18,true),nl=v.getUint16(i+26,true),extra=v.getUint16(i+28,true);if(method!==0||flags&8)throw Error('Цей ZIP використовує стиснення. Імпортуй архів, створений Academy.');const start=i+30+nl+extra;if(start+size>b.length)throw Error('Пошкоджений ZIP');const name=dec.decode(b.slice(i+30,i+30+nl));if(name.includes('..')||name.startsWith('/'))throw Error('Небезпечне ім’я файлу');const data=b.slice(start,start+size);if(crc32(data)!==v.getUint32(i+14,true))throw Error('Помилка цілісності ZIP');out.set(name,data);i=start+size;}return out}
export function zipText(data){return dec.decode(data)}
export function saveBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
